{
  "findings": [
    {
      "check_id": "CKV_AWS_40",
      "title": "Ensure IAM policies are attached only to groups or roles",
      "resource": "aws_iam_user_policy_attachment.privesc19-UpdateExistingGlueDevEndpoint-user-attach-policy",
      "severity": "MEDIUM",
      "explanation": "Attaching policies directly to IAM users increases the complexity of access management and can lead to excessive privileges. It is recommended to attach policies to IAM groups or roles instead, which can then be assigned to users."
    }
  ],
  "patched_code": "resource "aws_iam_group" "privesc19-UpdateExistingGlueDevEndpoint-group" {
  name = "privesc19-UpdateExistingGlueDevEndpoint-group"
}

resource "aws_iam_group_policy_attachment" "privesc19-UpdateExistingGlueDevEndpoint-group-attach-policy" {
  group      = aws_iam_group.privesc19-UpdateExistingGlueDevEndpoint-group.name
  policy_arn = aws_iam_policy.privesc19-UpdateExistingGlueDevEndpoint.arn
}

resource "aws_iam_user_group_membership" "privesc19-UpdateExistingGlueDevEndpoint-user-group-membership" {
  user = aws_iam_user.privesc19-UpdateExistingGlueDevEndpoint-user.name
  groups = [
    aws_iam_group.privesc19-UpdateExistingGlueDevEndpoint-group.name
  ]
}",
  "fix_summary": "Replaced the direct attachment of the policy to the IAM user with a group-based approach. Created an IAM group, attached the policy to the group, and added the user to the group to maintain the same permissions while improving access management practices."
}
